<div class="cav2-banco" id="cav2Banco"><button type="button" class="cav2-chip" draggable="true" data-key="prisioneros">Prisioneros</button> <button type="button" class="cav2-chip" draggable="true" data-key="cadenas">Cadenas</button> <button type="button" class="cav2-chip" draggable="true" data-key="sombras">Sombras</button> <button type="button" class="cav2-chip" draggable="true" data-key="fuego">Fuego</button> <button type="button" class="cav2-chip" draggable="true" data-key="exterior">El exterior</button></div>
