<p>
<script>
(function(){
'use strict';
function $(id){return document.getElementById(id);}
function shuffle(a){for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;}return a;}

/* ---------- Reflexión: guardar (opcional; si falla, no afecta al contenido) ---------- */
var ta=$('cav2Respuesta');
try{var prev=localStorage.getItem('cav21-reflexion');if(prev)ta.value=prev;}catch(e){}
 $('cav2Guardar').addEventListener('click',function(){
  try{localStorage.setItem('cav21-reflexion',ta.value);
    var e=$('cav2Estado');e.textContent='Respuesta guardada en este navegador.';
    setTimeout(function(){e.textContent='';},2600);
  }catch(err){$('cav2Estado').textContent='Este navegador no permite guardar.';}
});

/* ---------- Drag & Drop ---------- */
var banco=$('cav2Banco'),zona=$('cav2Zona'),hint=$('cav2Hint');
var aciertos=0,intentos=0,sel=null;
var PISTAS={usuarios:'Los prisioneros son personas reales: hoy miran una pantalla.',
algoritmo:'Las cadenas no dejan girar la cabeza: el algoritmo decide qué ves.',
posts:'Las sombras son lo único que los prisioneros ven proyectado en la pared.',
likes:'El fuego crea la luz que hace atractivas las sombras.',
critico:'El exterior es el mundo real: solo se llega contrastando por uno mismo.'};
function marcador(){$('cav2Aciertos').textContent=aciertos;$('cav2Intentos').textContent=intentos;}
function slots(){return Array.prototype.slice.call(zona.querySelectorAll('.cav2-slot'));}
function chips(){return Array.prototype.slice.call(document.querySelectorAll('.cav2-chip'));}
function deselecciona(){if(sel){sel.classList.remove('sel');sel=null;}}

function intento(chip,slot){
  if(chip.classList.contains('colocada')||slot.classList.contains('hecho'))return;
  intentos++;marcador();
  if(chip.getAttribute('data-key')===slot.getAttribute('data-key')){
    slot.classList.add('hecho');
    var p=slot.querySelector('.pista');if(p)p.style.display='none';
    chip.classList.remove('sel');chip.classList.add('colocada');
    slot.insertBefore(chip,slot.firstChild);
    aciertos++;marcador();hint.textContent='';deselecciona();
    if(aciertos===5){
      $('cav2FinTxt').textContent='Completado en '+intentos+' intentos.';
      $('cav2Fin').classList.add('visible');
    }
  }else{
    slot.classList.add('error');
    setTimeout(function(){slot.classList.remove('error');},450);
    hint.textContent='✗ Eso no encaja ahí. Pista: '+PISTAS[slot.getAttribute('data-key')];
    deselecciona();
  }
}

/* Selección por clic/toque/teclado */
chips().forEach(function(chip){
  chip.addEventListener('click',function(){
    if(chip.classList.contains('colocada'))return;
    if(sel===chip){deselecciona();hint.textContent='';}
    else{deselecciona();sel=chip;chip.classList.add('sel');hint.textContent='Ficha seleccionada: ahora toca su destino.';}
  });
});
slots().forEach(function(slot){
  slot.addEventListener('click',function(){if(sel)intento(sel,slot);});
  /* Arrastre HTML5 */
  slot.addEventListener('dragover',function(e){e.preventDefault();slot.classList.add('over');});
  slot.addEventListener('dragleave',function(){slot.classList.remove('over');});
  slot.addEventListener('drop',function(e){
    e.preventDefault();slot.classList.remove('over');
    var key=e.dataTransfer.getData('text/plain');
    var chip=document.querySelector('.cav2-chip[data-key="'+key+'"]');
    if(chip)intento(chip,slot);
  });
});
chips().forEach(function(chip){
  chip.addEventListener('dragstart',function(e){
    e.dataTransfer.setData('text/plain',chip.getAttribute('data-key'));
  });
});

/* Reinicio y mezcla inicial */
function reiniciar(){
  deselecciona();aciertos=0;intentos=0;marcador();
  hint.textContent='';$('cav2Fin').classList.remove('visible');
  slots().forEach(function(s){
    s.classList.remove('hecho','over');
    var p=s.querySelector('.pista');if(p)p.style.display='';
    var c=s.querySelector('.cav2-chip');if(c)banco.appendChild(c);
  });
  var cs=chips();shuffle(cs).forEach(function(c){banco.appendChild(c);});
  var ss=slots();shuffle(ss).forEach(function(s){zona.appendChild(s);});
}
 $('cav2Reiniciar').addEventListener('click',reiniciar);
reiniciar();
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

