<p>
<script>
(function(){
'use strict';
function $(id){return document.getElementById(id);}
var CORRECTAS={q1:'b',q2:'c',q3:'b',q4:'b',q5:'v'};
var TEXTO={q1:'Solo ven las sombras proyectadas en la pared',q2:'Las cadenas',q3:'Los memes, posts y titulares',q4:'Contrastar la información y buscar fuentes diversas',q5:'Verdadero'};

/* Guardado de la pregunta abierta */
var ab=$('evAbierta');
try{var prev=localStorage.getItem('cav21-eval');if(prev)ab.value=prev;}catch(e){}
 $('evGuardaAbierta').addEventListener('click',function(){
  try{localStorage.setItem('cav21-eval',ab.value);
    var e=$('evEstadoAbierta');e.textContent='Reflexión guardada.';
    setTimeout(function(){e.textContent='';},2600);
  }catch(err){$('evEstadoAbierta').textContent='No se pudo guardar en este navegador.';}
});

/* Corrección */
 $('evCorregir').addEventListener('click',function(){
  var fieldsets=document.querySelectorAll('.ev-q');
  var sinResponder=0,score=0;
  fieldsets.forEach(function(fs){
    var q=fs.dataset.q;if(q==='6')return;
    var elegida=fs.querySelector('input:checked');
    fs.classList.remove('ok','mal','falta');
    fs.querySelectorAll('.ev-op').forEach(function(o){o.classList.remove('es-correcta','elegida-mal');});
    if(!elegida){sinResponder++;fs.classList.add('falta');return;}
    if(elegida.value===CORRECTAS['q'+q]){score++;fs.classList.add('ok');}
    else{fs.classList.add('mal');elegida.closest('.ev-op').classList.add('elegida-mal');
      var correcta=fs.querySelector('input[value="'+CORRECTAS['q'+q]+'"]');
      if(correcta)correcta.closest('.ev-op').classList.add('es-correcta');
      var fb=fs.querySelector('.ev-fb');
      if(fb)fb.innerHTML='<b>Respuesta correcta:</b> '+TEXTO['q'+q]+'. '+fb.innerHTML;
    }
  });
  var est=$('evEstado');
  if(sinResponder>0){est.textContent='Te faltan '+sinResponder+' pregunta(s) por responder.';}
  else{est.textContent='';}
  var res=$('evResultado');res.className='ev-resultado visible';
  $('evNota').textContent=score+' / 5';
  var msg;
  if(score===5){res.classList.add('bien');msg='Has salido de la caverna: distingues las sombras de la realidad con una mirada crítica afilada.';}
  else if(score>=3){res.classList.add('medio');msg='Estás a mitad del camino de salida. Repasa lo marcado en rojo y vuelve a intentarlo.';}
  else if(score>=1){res.classList.add('bajo');msg='Las sombras aún te retienen. Vuelve a la tabla comparativa de la página 3 y reintenta.';}
  else{res.classList.add('bajo');msg='Aún mirando la pared. Lee con calma la página 3, juega al emparejamiento y vuelve a probar.';}
  $('evMensaje').textContent=msg;
  $('evReintentar').style.display='inline-block';
  res.scrollIntoView({behavior:'smooth',block:'center'});
});

/* Reintento */
 $('evReintentar').addEventListener('click',function(){
  document.querySelectorAll('.ev-q').forEach(function(fs){
    fs.classList.remove('ok','mal','falta');
    fs.querySelectorAll('input[type=radio]').forEach(function(r){r.checked=false;});
    fs.querySelectorAll('.ev-op').forEach(function(o){o.classList.remove('es-correcta','elegida-mal');});
  });
  $('evResultado').className='ev-resultado';
  $('evReintentar').style.display='none';
  $('evEstado').textContent='';
  window.scrollTo({top:0,behavior:'smooth'});
});
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

