<style>
.cg{--fondo:#0b0714;--panel:#151021;--panel2:#1e1433;--tinta:#f5eee2;--dim:#b9a8c9;--ambar:#ffb020;--fuego:#ff5a1f;--rosa:#ff2e63;--cielo:#35e0ff;--verde:#3ddc84;
font-family:'Trebuchet MS',Verdana,Arial,sans-serif;color:var(--tinta);background:var(--fondo);border-radius:16px;line-height:1.55;font-size:16px;max-width:860px;margin:0 auto;padding:0 0 30px;position:relative;overflow:hidden}
.cg *,.cg *::before,.cg *::after{box-sizing:border-box}
.cg .kick{font-size:11px;font-weight:700;letter-spacing:.28em;text-transform:uppercase;color:var(--ambar);margin:0 0 10px}
.cg h1{font-size:clamp(34px,6vw,54px);font-weight:900;text-transform:uppercase;letter-spacing:.02em;line-height:1.02;margin:0 0 14px;text-shadow:0 0 24px rgba(255,90,31,.55),0 0 60px rgba(255,90,31,.25)}
.cg h2{font-size:24px;font-weight:900;text-transform:uppercase;margin:0 0 8px}
.cg p{margin:0 0 1em}
.cg .tambien{color:var(--dim)}

/* ---- Ambiente: brillo del fuego + motas ---- */
.cg-brillo{position:absolute;left:50%;bottom:-120px;width:560px;height:560px;transform:translateX(-50%);background:radial-gradient(circle,rgba(255,90,31,.35),rgba(255,90,31,0) 65%);pointer-events:none;animation:cguFuego 3.2s ease-in-out infinite alternate}
@keyframes cguFuego{from{opacity:.55;transform:translateX(-50%) scale(1)}to{opacity:1;transform:translateX(-50%) scale(1.12)}}
.cg-motas{position:absolute;inset:0;pointer-events:none;overflow:hidden}
.cg-motas i{position:absolute;bottom:-10px;width:4px;height:4px;border-radius:50%;background:rgba(255,176,32,.5);animation:cguSube linear infinite}
@keyframes cguSube{to{transform:translateY(-110vh);opacity:0}}

/* ---- Pantallas ---- */
.cg .pantalla{display:none;position:relative;padding:34px 30px 10px}
.cg .pantalla.activa{display:block}
.cg .centro{text-align:center}
.cg .mini{font-size:13.5px;color:var(--dim)}
.cg .reglas{list-style:none;padding:0;margin:18px auto;max-width:420px;text-align:left}
.cg .reglas li{padding:9px 0;border-top:1px solid rgba(255,255,255,.1);font-size:14.5px}
.cg .reglas li:first-child{border-top:none}

/* ---- HUD ---- */
.cg-hud{display:none;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:16px 22px;border-bottom:1px solid rgba(255,255,255,.12);background:rgba(0,0,0,.35);position:relative}
.cg-hud.visible{display:flex}
.cg-vidas{font-size:20px;letter-spacing:3px}
.cg-puntos{font-size:20px;font-weight:900;color:var(--ambar);text-shadow:0 0 12px rgba(255,176,32,.5)}
.cg-salas{display:flex;gap:6px;font-size:15px}
.cg-salas span{opacity:.3;filter:grayscale(1)}
.cg-salas span.actual{opacity:1;filter:none;transform:scale(1.2)}
.cg-salas span.hecha{opacity:.85;filter:none}
.cg-silencio{background:none;border:2px solid rgba(255,255,255,.25);color:var(--tinta);border-radius:10px;font-size:16px;cursor:pointer;padding:4px 10px}
.cg-silencio:hover{border-color:var(--ambar)}

/* ---- Botones ---- */
.cg-btn{font-family:inherit;font-size:17px;font-weight:900;text-transform:uppercase;letter-spacing:.06em;color:var(--ambar);background:transparent;border:3px solid var(--ambar);border-radius:14px;padding:14px 28px;cursor:pointer;box-shadow:0 0 20px rgba(255,176,32,.25);transition:transform .12s,background .2s,color .2s,box-shadow .2s}
.cg-btn:hover{background:var(--ambar);color:#1a0f05;box-shadow:0 0 34px rgba(255,176,32,.6)}
.cg-btn:active{transform:translateY(2px) scale(.98)}
.cg-btn.sec{border-color:rgba(255,255,255,.35);color:var(--dim);box-shadow:none;font-size:14px;padding:10px 20px}
.cg-btn.sec:hover{background:rgba(255,255,255,.12);color:var(--tinta)}

/* ---- Elección (salas 1 y 2) ---- */
.cg-elec-sala{font-size:12px;font-weight:900;letter-spacing:.24em;text-transform:uppercase;color:var(--cielo);text-align:center;margin:6px 0 4px}
.cg-prog{font-size:13px;font-weight:700;color:var(--dim);text-align:center;margin:0 0 10px}
.cg-tarjeta{background:var(--panel2);border:2px solid rgba(255,255,255,.14);border-radius:18px;padding:28px 26px;min-height:130px;display:flex;align-items:center;justify-content:center;text-align:center;font-size:21px;font-weight:700;margin:0 0 14px;animation:cguPop .28s ease}
@keyframes cguPop{from{transform:scale(.92);opacity:0}to{transform:scale(1);opacity:1}}
.cg-tbar{height:8px;border-radius:99px;background:rgba(255,255,255,.1);overflow:hidden;margin:0 0 18px}
.cg-tfill{height:100%;width:100%;background:linear-gradient(90deg,var(--ambar),var(--rosa));border-radius:99px}
.cg-dos{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}
.cg-opc{flex:1 1 200px;max-width:280px;font-family:inherit;font-size:18px;font-weight:900;text-transform:uppercase;letter-spacing:.04em;padding:20px 12px;border-radius:16px;border:3px solid;background:transparent;cursor:pointer;transition:transform .1s,box-shadow .2s,background .2s}
.cg-opc small{display:block;font-size:11px;letter-spacing:.2em;font-weight:700;opacity:.75;margin-bottom:4px}
.cg-opc:active{transform:scale(.96)}
.cg-opc.izq{border-color:var(--fuego);color:var(--fuego)}
.cg-opc.izq:hover{background:rgba(255,90,31,.16);box-shadow:0 0 24px rgba(255,90,31,.4)}
.cg-opc.der{border-color:var(--cielo);color:var(--cielo)}
.cg-opc.der:hover{background:rgba(53,224,255,.14);box-shadow:0 0 24px rgba(53,224,255,.4)}
.cg-flota{position:fixed;left:50%;top:30%;transform:translateX(-50%);font-size:30px;font-weight:900;pointer-events:none;z-index:50;animation:cguFlota .9s ease forwards;text-shadow:0 2px 14px rgba(0,0,0,.8)}
@keyframes cguFlota{from{opacity:0;transform:translate(-50%,16px) scale(.8)}20%{opacity:1;transform:translate(-50%,0) scale(1.05)}to{opacity:0;transform:translate(-50%,-44px) scale(1)}}
.cg-sacude{animation:cguSaca .38s ease}
@keyframes cguSaca{0%,100%{transform:translateX(0)}20%{transform:translateX(-9px)}45%{transform:translateX(8px)}70%{transform:translateX(-5px)}}

/* ---- Sala del fuego ---- */
.cg-arena{position:relative;height:360px;border:3px solid rgba(255,90,31,.4);border-radius:18px;overflow:hidden;background:linear-gradient(180deg,#0b0714,#1a0f2e);margin:0 0 14px;cursor:crosshair}
.cg-arena .elem{position:absolute;bottom:-90px;font-size:46px;line-height:1;cursor:pointer;user-select:none;-webkit-user-select:none;filter:drop-shadow(0 0 10px rgba(255,90,31,.45));animation:cguSubeElem linear forwards}
@keyframes cguSubeElem{to{transform:translateY(-490px)}}
.cg-arena .elem.sol{filter:drop-shadow(0 0 12px rgba(53,224,255,.6))}
.cg-contafuego{display:flex;justify-content:center;gap:20px;font-size:18px;font-weight:900}

/* ---- Sala de las llaves ---- */
.cg-llaves{display:flex;justify-content:center;gap:10px;font-size:28px;margin:0 0 16px}
.cg-llaves span{opacity:.25;filter:grayscale(1);transition:all .3s}
.cg-llaves span.on{opacity:1;filter:none;text-shadow:0 0 16px rgba(255,176,32,.8)}
.cg-ops4{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.cg-ops4 button{font-family:inherit;font-size:15.5px;font-weight:700;color:var(--tinta);text-align:left;background:var(--panel);border:2px solid rgba(255,255,255,.2);border-radius:14px;padding:14px 16px;cursor:pointer;transition:border-color .2s,background .2s}
.cg-ops4 button:hover{border-color:var(--ambar);background:rgba(255,176,32,.08)}
.cg-ops4 button:disabled{cursor:default;opacity:.65}

/* ---- Paneles finales ---- */
.cg-panel{background:var(--panel2);border:2px solid rgba(255,255,255,.14);border-radius:20px;padding:30px 26px;max-width:520px;margin:0 auto;text-align:center}
.cg-rango{font-size:64px;line-height:1;margin:10px 0 6px;filter:drop-shadow(0 0 18px rgba(255,176,32,.6))}
.cg-merito{font-size:22px;font-weight:900;text-transform:uppercase;color:var(--ambar);margin:0 0 12px}
.cg-num{font-size:34px;font-weight:900;color:var(--tinta)}
@media (max-width:640px){.cg .pantalla{padding:26px 16px 6px}.cg-ops4{grid-template-columns:1fr}.cg-arena{height:300px}.cg-arena .elem{font-size:40px}}
@media (prefers-reduced-motion:reduce){.cg-brillo,.cg-motas i,.cg-tarjeta,.cg-flota,.cg-arena .elem,.cg-sacude{animation:none!important}}
</style>
<div class="cg" id="cgJuego">
<div class="cg-brillo" aria-hidden="true"><br /></div>
<div class="cg-motas" id="cgMotas" aria-hidden="true"></div>
<!-- ====== HUD ====== -->
<div class="cg-hud" id="cgHud"><span class="cg-vidas" id="cgVidas" aria-label="Vidas">❤️❤️❤️</span> <span class="cg-puntos"><span id="cgPuntos">0</span> pts</span> <span class="cg-salas" id="cgSalas"><span data-s="1">⛓️</span><span data-s="2">👥</span><span data-s="3">🔥</span><span data-s="4">🔑</span></span> <button type="button" class="cg-silencio" id="cgMute" aria-label="Activar o silenciar sonido">🔊</button></div>
<!-- ====== INICIO ====== -->
<section class="pantalla activa centro" id="cgInicio">
<p class="kick">Parada 3 · La Caverna en el siglo XXI · Videojuego</p>
<h1>Escapa de<br />la caverna</h1>
<p class="tambien" style="max-width: 52ch; margin: 0 auto 6px;">Llevas horas mirando la pared. El feed proyecta sus sombras, el fuego de los likes parpadea y tus cadenas no se ven… porque las llevas puestas por dentro.</p>
<p style="font-weight: bold; font-size: 18px;">Tienes <span style="color: var(--fuego);">3 vidas</span> y <span style="color: var(--cielo);">4 salas</span> entre tú y la luz.</p>
<ul class="reglas">
<li>⛓️ <b>Sala 1 — La pared:</b> ¿cadena o libertad? Decide rápido.</li>
<li>👥 <b>Sala 2 — Las sombras:</b> ¿sombra o realidad? No te dejes engañar.</li>
<li>🔥 <b>Sala 3 — El fuego:</b> coge los 🌅 y toca el menor 🔥 posible.</li>
<li>🔑 <b>Sala 4 — La salida:</b> responde y gana las 3 llaves de la puerta.</li>
</ul>
<p><button type="button" class="cg-btn" id="cgEmpezar">🔥 Entrar en la caverna</button></p>
<p class="mini">Mejor puntuación: <b id="cgRecord">—</b> pts · El juego guarda tu récord en este navegador.</p>
<noscript><p class="mini">Este minijuego necesita JavaScript activado. El contenido de la Parada 3 está disponible en su página correspondiente.</p></noscript></section>
<!-- ====== JUEGO ====== -->
<section class="pantalla" id="cgJugando"><!-- Interstitial de sala -->
<div class="centro" id="cgInter">
<p class="kick" id="cgInterSala">Sala 1 de 4</p>
<h2 id="cgInterTit" style="font-size: 30px;">—</h2>
<p class="tambien" id="cgInterTxt" style="max-width: 50ch; margin: 0 auto 18px;">—</p>
<button type="button" class="cg-btn" id="cgInterBtn">Empezar</button></div>
<!-- Salas 1 y 2: elección -->
<div id="cgElec" hidden="">
<p class="cg-elec-sala" id="cgElecSala">—</p>
<p class="cg-prog" id="cgElecProg">0/10</p>
<div class="cg-tarjeta" id="cgElecTxt">—</div>
<div class="cg-tbar">
<div class="cg-tfill" id="cgElecT"></div>
</div>
<div class="cg-dos"><button type="button" class="cg-opc izq" id="cgElecIzq"><small id="cgElecIzqE">⛓️</small><span id="cgElecIzqT">Cadena</span></button> <button type="button" class="cg-opc der" id="cgElecDer"><small id="cgElecDerE">🕊️</small><span id="cgElecDerT">Libertad</span></button></div>
</div>
<!-- Sala 3: el fuego -->
<div id="cgFuego" hidden="">
<p class="cg-elec-sala" style="color: var(--fuego);">Sala 3 · El fuego de los likes</p>
<p class="cg-prog">Los 🔥 suben y brillan… <b style="color: var(--cielo);">tú solo quieres los 🌅</b>. Tocar un fuego = perder vida.</p>
<div class="cg-arena" id="cgArena"></div>
<div class="cg-contafuego"><span>🌅 <span id="cgSoles">0</span>/8</span><span style="color: var(--fuego);">🔥 tocados: <span id="cgFuegos">0</span></span></div>
</div>
<!-- Sala 4: llaves -->
<div id="cgLlaves" hidden="">
<p class="cg-elec-sala" style="color: var(--verde);">Sala 4 · La puerta de la salida</p>
<p class="cg-prog">Responde bien para ganar llaves. Con 3 🔑 se abre la puerta.</p>
<div class="cg-llaves" id="cgLlaveRow"><span>🔑</span><span>🔑</span><span>🔑</span></div>
<div class="cg-tarjeta" id="cgLlaveTxt" style="font-size: 18px; min-height: 110px;">—</div>
<div class="cg-tbar">
<div class="cg-tfill" id="cgLlaveT"></div>
</div>
<div class="cg-ops4" id="cgLlaveOps"></div>
</div>
<!-- Fin de sala -->
<div class="centro" id="cgFinSala" hidden="">
<div class="cg-panel">
<p class="kick" id="cgFsSala">Sala superada</p>
<p style="font-size: 52px; line-height: 1; margin: 6px 0;" id="cgFsIcono">✨</p>
<h2 id="cgFsTit" style="font-size: 22px;">—</h2>
<p class="tambien" id="cgFsTxt" style="margin: 0 0 14px;">—</p>
<button type="button" class="cg-btn" id="cgFsBtn">Continuar →</button></div>
</div>
</section>
<!-- ====== FINAL ====== -->
<section class="pantalla centro" id="cgFin">
<p class="kick">Has llegado a la luz</p>
<div class="cg-rango" id="cgFinEmoji">🌅</div>
<p class="cg-merito" id="cgFinRango">—</p>
<div class="cg-panel">
<p class="mini">Puntuación</p>
<p class="cg-num"><span id="cgFinPts">0</span> pts</p>
<p class="mini" id="cgFinRecord"></p>
<p class="tambien" id="cgFinTxt" style="font-size: 14.5px;">—</p>
</div>
<p style="margin-top: 18px;"><button type="button" class="cg-btn" id="cgOtra">Reintentar la caverna</button></p>
<p class="mini" style="margin-top: 14px;">Pregunta honesta: <b>¿cuántas veces has tocado el 🔥 hoy… fuera del juego?</b> Vuelve a la Parada 3 y repásalo con el mapa de la alegoría.</p>
</section>
<!-- ====== GAME OVER ====== -->
<section class="pantalla centro" id="cgOver">
<p class="kick" style="color: var(--rosa);">El fuego te ha atrapado</p>
<div class="cg-rango">⛓️</div>
<p class="cg-merito" style="color: var(--rosa);">Sigue prisionero… por ahora</p>
<div class="cg-panel">
<p class="mini">Puntuación conseguida</p>
<p class="cg-num"><span id="cgOverPts">0</span> pts</p>
<p class="tambien" style="font-size: 14.5px;">En la caverna no pasa nada por reintentarlo: es lo que hace distinta a esta de la de verdad. Ahí fuera también puedes empezar de cero, cada día.</p>
</div>
<p style="margin-top: 18px;"><button type="button" class="cg-btn" id="cgOtra2">Volver a intentarlo</button></p>
</section>
</div>
<p>
<script>
(function(){
'use strict';
/* =========================================================
   CONFIGURACIÓN RÁPIDA (docente): textos, tiempos y puntos.
   ========================================================= */
var VIDAS_INICIO=3;

var NIVEL1=[
 {t:'Miro el móvil al despertar antes que a ninguna persona.',c:'izq'},
 {t:'Decido yo cuándo entro en la red y cuándo salgo.',c:'der'},
 {t:'Silencio las notificaciones durante una tarde completa.',c:'der'},
 {t:'«Solo cinco minutos de scroll»… (han pasado 45).',c:'izq'},
 {t:'Compruebo cada 10 minutos cuántos likes lleva mi foto.',c:'izq'},
 {t:'Quedo con mis amigos y no lo publico en ningún sitio.',c:'der'},
 {t:'Sigo solo a cuentas que piensan exactamente como yo.',c:'izq'},
 {t:'Busco una segunda fuente antes de reenviar algo.',c:'der'},
 {t:'Duermo con el móvil debajo de la almohada.',c:'izq'},
 {t:'Hoy aprendo algo nuevo solo porque me da curiosidad.',c:'der'}];

var NIVEL2=[
 {t:'Un reel perfecto de unas vacaciones de ensueño.',c:'izq'},
 {t:'Las vacaciones de verdad: mosquitos incluidos.',c:'der'},
 {t:'Un titular en mayúsculas diseñado para indignarte.',c:'izq'},
 {t:'Un informe entero, leído completo, con sus datos.',c:'der'},
 {t:'El cuerpo «antes y después» retocado por un filtro.',c:'izq'},
 {t:'Tu cuerpo real: el que corre, duerme y se ríe.',c:'der'},
 {t:'La vida de tus seguidores según sus stories.',c:'izq'},
 {t:'Una charla cara a cara con alguien que te cae bien.',c:'der'},
 {t:'Un vídeo viral de 15 segundos que «lo explica todo».',c:'izq'},
 {t:'Un atardecer visto con los ojos, sin grabarlo.',c:'der'}];

var NIVEL4=[
 {p:'En la alegoría, ¿qué representan las CADENAS hoy?',
  ops:['Los auriculares con cable','El algoritmo y el scroll infinito, que deciden qué ves','La contraseña del WiFi','La funda del móvil'],ok:1},
 {p:'¿Qué son las SOMBRAS proyectadas en la pared?',
  ops:['Las fotos en blanco y negro','La luz de las velas','Los posts, memes y titulares que parecen el mundo entero','Las notificaciones silenciadas'],ok:2},
 {p:'¿Cuál es el FUEGO de tu caverna digital?',
  ops:['El cargador del móvil','Las notificaciones y los likes, que hacen brillar las sombras','La linterna del móvil','El modo oscuro de las apps'],ok:1},
 {p:'¿Qué significa SALIR de la caverna?',
  ops:['Tirar el móvil al mar','Entrar en modo avión una vez al año','Contrastar fuentes y mirar el mundo con ojos propios','Cambiar de red social'],ok:2},
 {p:'Platón vería el deepfake del papa con abrigo como…',
  ops:['Una sombra fabricada por una nueva clase de artesanos','Un abrigo muy bonito','La prueba de que el papa es moderno','Un problema de los diseñadores'],ok:0}];

var SALAS=[
 {icono:'⛓️',tit:'Sala 1 · La pared',txt:'Leerás 10 frases de la vida diaria. Decide en segundos: ¿te CADENA (⛓️) o te LIBERA (🕊️)? El tiempo corre: cada decisión tiene su reloj.',
  punt:'Cada acierto: 100 pts + bonus por racha.'},
 {icono:'👥',tit:'Sala 2 · Las sombras',txt:'Esto que ves pasar en la pantalla… ¿es una SOMBRA (👥) de la realidad o es REALIDAD (🌍)? Reflejos más rápidos que en la sala anterior.',
  punt:'Cada acierto: 100 pts + bonus por racha.'},
 {icono:'🔥',tit:'Sala 3 · El fuego',txt:'Los likes (🔥) suben del fondo, brillando y pidiendo ser tocados. Resiste: coge 8 soles (🌅) y toca el menor número de fuegos. Tocar un fuego quita una vida.',
  punt:'Cada sol: 150 pts.'},
 {icono:'🔑',tit:'Sala 4 · La salida',txt:'La puerta de la caverna tiene 3 cerraduras. Responde correctamente y gana llaves (necesitas 3). Fallar quita una vida… pero puedes conseguir las llaves que falten en las preguntas siguientes.',
  punt:'Cada llave: 200 pts.'}];

/* =========================================================
   MOTOR DEL JUEGO
   ========================================================= */
function $(id){return document.getElementById(id);}
var scr={inicio:$('cgInicio'),jugando:$('cgJugando'),fin:$('cgFin'),over:$('cgOver')};
var vidas=0,puntos=0,racha=0,sala=0,soles=0,fuegos=0,llaves=0;
var temp=null,spawner=null;
var silencio=false,ctxAudio=null;
var sonando=false;

/* --- Sonido (WebAudio; si falla, el juego sigue igual) --- */
function beep(f1,f2,dur,tipo){
  if(silencio)return;
  try{
    if(!ctxAudio)ctxAudio=new (window.AudioContext||window.webkitAudioContext)();
    var o=ctxAudio.createOscillator(),g=ctxAudio.createGain(),t=ctxAudio.currentTime;
    o.type=tipo||'square';o.frequency.setValueAtTime(f1,t);
    if(f2)o.frequency.exponentialRampToValueAtTime(f2,t+dur);
    g.gain.setValueAtTime(0.07,t);g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
    o.connect(g);g.connect(ctxAudio.destination);o.start(t);o.stop(t+dur);
  }catch(e){}
}
function sBien(){beep(620,980,.16);} function sMal(){beep(170,90,.3,'sawtooth');}
function sLlave(){beep(520,1040,.25,'triangle');} function sPop(){beep(760,760,.08,'triangle');}

 $('cgMute').addEventListener('click',function(){
  silencio=!silencio;this.textContent=silencio?'🔇':'🔊';
});

/* --- Motas de fondo --- */
(function(){
  var cont=$('cgMotas');
  for(var i=0;i<14;i++){
    var m=document.createElement('i');
    m.style.left=(Math.random()*100)+'%';
    m.style.animationDuration=(7+Math.random()*9)+'s';
    m.style.animationDelay=(Math.random()*8)+'s';
    m.style.opacity=0.25+Math.random()*0.5;
    cont.appendChild(m);
  }
})();

/* --- Navegación de pantallas --- */
function ver(nombre){
  Object.keys(scr).forEach(function(k){scr[k].classList.toggle('activa',k===nombre);});
}
function pantallaJuego(bloque){
  ver('jugando');
  $('cgHud').classList.add('visible');
  ['cgInter','cgElec','cgFuego','cgLlaves','cgFinSala'].forEach(function(id){$(id).hidden=(id!==bloque);});
  $('cgInter').hidden=(bloque!=='cgInter');
}
function hud(){
  $('cgVidas').textContent=new Array(Math.max(vidas,0)+1).join('❤️')||'💀';
  $('cgPuntos').textContent=puntos;
  Array.prototype.forEach.call($('cgSalas').children,function(s,i){
    s.className=(i+1)<sala?'hecha':(i+1)===sala?'actual':'';
  });
}
function limpiaTimers(){
  if(temp){clearInterval(temp);temp=null;}
  if(spawner){clearInterval(spawner);spawner=null;}
}
function flota(txt,color){
  var f=document.createElement('div');
  f.className='cg-flota';f.textContent=txt;f.style.color=color;
  document.body.appendChild(f);
  setTimeout(function(){f.remove();},950);
}
function pierdeVida(){
  vidas--;hud();sMal();
  scr.jugando.classList.add('cg-sacude');
  setTimeout(function(){scr.jugando.classList.remove('cg-sacude');},400);
  if(vidas<=0){limpiaTimers();gameOver();}
}
function resetear(){
  vidas=VIDAS_INICIO;puntos=0;racha=0;sala=0;soles=0;fuegos=0;llaves=0;limpiaTimers();hud();
}
function pintaRecord(){
  var r=null;try{r=localStorage.getItem('cav3-record');}catch(e){}
  $('cgRecord').textContent=r?r:'—';
}
pintaRecord();

/* --- Interstitial de sala --- */
function salaIntro(n){
  sala=n;limpiaTimers();hud();
  var s=SALAS[n-1];
  $('cgInterSala').textContent='Sala '+n+' de 4 · '+s.punt;
  $('cgInterTit').textContent=s.icono+' '+s.tit;
  $('cgInterTxt').textContent=s.txt;
  pantallaJuego('cgInter');
}
 $('cgInterBtn').addEventListener('click',function(){
  beep(440,660,.12);
  if(sala===1||sala===2)eleccionStart(sala);
  else if(sala===3)fuegoStart();
  else llavesStart();
});

/* ============ SALAS 1 Y 2: elección ============ */
var eleCfg=null;
function eleccionStart(n){
  eleCfg={items:n===1?NIVEL1.slice():NIVEL2.slice(),idx:0,
    tMs:n===1?8000:6000,
    izq:n===1?{e:'⛓️',t:'Cadena'}:{e:'👥',t:'Sombra'},
    der:n===1?{e:'🕊️',t:'Libertad'}:{e:'🌍',t:'Realidad'}};
  $('cgElecSala').textContent='Sala '+n+' · '+(n===1?'¿Cadena o libertad?':'¿Sombra o realidad?');
  $('cgElecIzqE').textContent=eleCfg.izq.e;$('cgElecIzqT').textContent=eleCfg.izq.t;
  $('cgElecDerE').textContent=eleCfg.der.e;$('cgElecDerT').textContent=eleCfg.der.t;
  pantallaJuego('cgElec');
  eleccionPinta();
}
function eleccionPinta(){
  var it=eleCfg.items[eleCfg.idx];
  $('cgElecProg').textContent=(eleCfg.idx+1)+'/'+eleCfg.items.length;
  var tar=$('cgElecTxt');tar.textContent='“'+it.t+'”';
  tar.style.animation='none';void tar.offsetWidth;tar.style.animation='';
  eleccionTimer();
}
function eleccionTimer(){
  clearInterval(temp);
  var fin=Date.now()+eleCfg.tMs,fill=$('cgElecT');
  fill.style.width='100%';
  temp=setInterval(function(){
    var rest=fin-Date.now();
    fill.style.width=Math.max(0,rest/eleCfg.tMs*100)+'%';
    if(rest<=0){clearInterval(temp);temp=null;fallo();eleccionAvanza();}
  },80);
}
function fallo(){racha=0;flota('✗ Se escapa…','var(--rosa)');pierdeVida();}
function acierto(base){
  racha++;
  var bonus=Math.min(racha-1,4)*25,p=base+bonus;
  puntos+=p;hud();sBien();
  flota('+'+p+(racha>1?' · RACHA x'+racha:''),'var(--verde)');
}
function eleccionResponde(lado){
  if(!temp&&!$('cgElecT').style.width)return;
  if(temp===null&&Date.now()){/* timeout ya gestionado */}
  clearInterval(temp);temp=null;
  var it=eleCfg.items[eleCfg.idx];
  if(it.c===lado)acierto(100);else fallo();
  eleccionAvanza();
}
function eleccionAvanza(){
  if(vidas<=0)return;
  eleCfg.idx++;
  if(eleCfg.idx>=eleCfg.items.length){
    salaFin('¡Pared superada!','Ya sabes reconocer qué te ata y qué te suelta. El siguiente paso es más difícil: distinguir lo real de lo proyectado.','👥');
  }else eleccionPinta();
}
 $('cgElecIzq').addEventListener('click',function(){eleccionResponde('izq');});
 $('cgElecDer').addEventListener('click',function(){eleccionResponde('der');});

/* ============ SALA 3: el fuego ============ */
function fuegoStart(){
  soles=0;fuegos=0;$('cgSoles').textContent=0;$('cgFuegos').textContent=0;
  var arena=$('cgArena');arena.innerHTML='';
  pantallaJuego('cgFuego');
  clearInterval(spawner);
  var n=0;
  spawner=setInterval(function(){
    n++;
    var esSol=(n%4===0); /* 1 de cada 4 elementos es un sol */
    spawnElem(arena,esSol);
    if(n>4)spawnElem(arena,false);
  },620);
}
function spawnElem(arena,esSol){
  var e=document.createElement('span');
  e.className='elem'+(esSol?' sol':'');
  e.textContent=esSol?'🌅':'🔥';
  e.style.left=(4+Math.random()*84)+'%';
  var dur=(esSol?4.2:3.4)+Math.random()*1.8;
  e.style.animationDuration=dur+'s';
  e.addEventListener('click',function(ev){
    ev.stopPropagation();
    if(esSol){
      soles++;puntos+=150;hud();$('cgSoles').textContent=soles;
      sPop();flota('+150','var(--cielo)');e.remove();
      if(soles>=8){limpiaTimers();
        salaFin('¡Ocho soles cogidos!','Has resistido el fuego: los likes seguían subiendo, brillando… y tú mirabas arriba. Eso es exactamente lo que pasa cuando dejas la teledirigida atención y eliges tú.','🔑');}
    }else{
      fuegos++;$('cgFuegos').textContent=fuegos;
      pierdeVida();e.remove();
    }
  });
  e.addEventListener('animationend',function(){e.remove();});
  arena.appendChild(e);
}

/* ============ SALA 4: llaves ============ */
var llaCfg=null;
function llavesStart(){
  llaCfg={idx:0,conseguidas:0};
  pintaLlaves();
  pantallaJuego('cgLlaves');
  llavePinta();
}
function pintaLlaves(){
  Array.prototype.forEach.call($('cgLlaveRow').children,function(s,i){
    s.className=i<llaves?'on':'';
  });
}
function llavePinta(){
  var q=NIVEL4[llaCfg.idx];
  $('cgLlaveTxt').textContent=q.p;
  var cont=$('cgLlaveOps');cont.innerHTML='';
  var fin=Date.now()+11000,fill=$('cgLlaveT');fill.style.width='100%';
  clearInterval(temp);
  temp=setInterval(function(){
    var rest=fin-Date.now();
    fill.style.width=Math.max(0,rest/11000*100)+'%';
    if(rest<=0){clearInterval(temp);temp=null;
      Array.prototype.forEach.call(cont.children,function(b){b.disabled=true;});
      flota('⌛ Tiempo','var(--rosa)');pierdeVida();llaveAvanza();}
  },80);
  q.ops.forEach(function(op,i){
    var b=document.createElement('button');
    b.type='button';b.textContent=op;
    b.addEventListener('click',function(){
      if(temp===null&&b.disabled)return;
      clearInterval(temp);temp=null;
      Array.prototype.forEach.call(cont.children,function(o){o.disabled=true;});
      if(i===q.ok){
        llaves++;llaCfg.conseguidas++;puntos+=200;hud();sLlave();pintaLlaves();
        flota('🔑 +200','var(--ambar)');
      }else{
        flota('✗ Llave fallida','var(--rosa)');pierdeVida();
      }
      setTimeout(llaveAvanza,700);
    });
    cont.appendChild(b);
  });
}
function llaveAvanza(){
  if(vidas<=0)return;
  if(llaves>=3){
    salaFin('¡La puerta se abre!','Tres llaves, tres respuestas correctas: entiendes qué te ata, qué es sombra, qué es fuego y qué significa salir. La luz es tuya.','🌅');
    return;
  }
  llaCfg.idx++;
  if(llaCfg.idx>=NIVEL4.length){
    limpiaTimers();gameOver();
  }else llavePinta();
}

/* ============ Fin de sala y final ============ */
function salaFin(tit,txt,icono){
  limpiaTimers();
  $('cgFsSala').textContent='Sala '+sala+' de 4 superada · '+puntos+' pts';
  $('cgFsIcono').textContent=icono;
  $('cgFsTit').textContent=tit;
  $('cgFsTxt').textContent=txt;
  $('cgFsBtn').textContent=sala<4?'Siguiente sala →':'¡Salir a la luz!';
  pantallaJuego('cgFinSala');
}
 $('cgFsBtn').addEventListener('click',function(){
  if(sala<4)salaIntro(sala+1);else final();
});
function final(){
  ver('fin');
  $('cgHud').classList.remove('visible');
  var r;
  if(puntos>=3200){$('cgFinEmoji').textContent='🌅';r='GUÍA DE LA CAVERNA';
    $('cgFinTxt').textContent='Nivel máximo: no solo has salido; vuelves a contar cómo se hace. Platón te daría trabajo.';}
  else if(puntos>=2400){$('cgFinEmoji').textContent='🧗';r='ESCAPISTA';
    $('cgFinTxt').textContent='Has salido con esfuerzo y cabeza. Mantén el hábito de mirar hacia arriba.';}
  else if(puntos>=1400){$('cgFinEmoji').textContent='👁️';r='DESPERTANDO';
    $('cgFinTxt').textContent='Ya distingues sombras de realidad… a ratos. Repite el juego: la salida se entrena.';}
  else{$('cgFinEmoji').textContent='⛓️';r='PRISIONERO CON GANAS DE SALIR';
    $('cgFinTxt').textContent='Has empezado a removerte en las cadenas: eso ya es más que la mayoría. Relee la Parada 3 y vuelve.';}
  $('cgFinRango').textContent=r;
  $('cgFinPts').textContent=puntos;
  var mejor=null;
  try{mejor=parseInt(localStorage.getItem('cav3-record'),10)||0;}catch(e){}
  if(puntos>mejor){
    try{localStorage.setItem('cav3-record',String(puntos));}catch(e){}
    $('cgFinRecord').textContent='🏆 ¡Nuevo récord personal!';
  }else{
    $('cgFinRecord').textContent='Tu récord sigue siendo '+mejor+' pts.';
  }
  pintaRecord();
}
function gameOver(){
  limpiaTimers();
  $('cgOverPts').textContent=puntos;
  ver('over');
  $('cgHud').classList.remove('visible');
}

/* ============ Arranque y reinicio ============ */
function empezar(){
  try{if(ctxAudio&&ctxAudio.state==='suspended')ctxAudio.resume();}catch(e){}
  resetear();salaIntro(1);
}
 $('cgEmpezar').addEventListener('click',empezar);
 $('cgOtra').addEventListener('click',empezar);
 $('cgOtra2').addEventListener('click',empezar);
})();
</script>
