<div class="fn5"><!-- ============ CABECERA ============ -->
<div class="fn5-cab">
<p class="fn5-k">Actividades evaluativas · Página 4 bis</p>
<h1>Caza de sombras</h1>
<p>Tres retos para demostrar que ya no miras la pared como un prisionero: un quiz con puntuación, la detección de pistas falsas en una publicación viral simulada y tu caja de herramientas de verificación. Juega las veces que quieras.</p>
</div>
<!-- ============ RETO 1: QUIZ ¿FAKE O REAL? ============ -->
<section class="fn5-sec">
<p class="fn5-k">Reto 1 · Gamificado</p>
<h2>¿Fake o real?</h2>
<p>Cinco afirmaciones que circularon (o circulan) por internet. Acierta: <strong>20 puntos</strong>. Responde «hay que verificarlo» cuando no estés seguro: <strong>10 puntos</strong> — verificar antes de creer también suma. Error: 0 puntos. Cada respuesta desvela su verificación posterior.</p>
<div class="fn5-marcador" aria-live="polite"><span class="pill">Puntos: <span id="fn5Pts">0</span>/100</span> <span class="pill">Respondidos: <span id="fn5Hechos">0</span>/5</span></div>
<form id="fn5Form" onsubmit="return false"><fieldset class="fn5-caso" data-key="c1"><legend>CASO 01</legend>
<blockquote>«La NASA confirma que el próximo 23 de agosto habrá 15 minutos de oscuridad total en todo el planeta por la alineación de los planetas. ¡Comparte antes de que lo borren!»</blockquote>
<div class="fn5-ops"><label><input type="radio" name="c1" value="falsa" />FAKE</label> <label><input type="radio" name="c1" value="real" />REAL</label> <label><input type="radio" name="c1" value="verificar" />Hay que verificarlo</label></div>
<div class="fn5-fb"><span class="marca"></span><span class="txt"></span><br /></div>
</fieldset><fieldset class="fn5-caso" data-key="c2"><legend>CASO 02</legend>
<blockquote>«La Torre Eiffel puede crecer hasta 15 centímetros durante el verano a causa del calor».</blockquote>
<div class="fn5-ops"><label><input type="radio" name="c2" value="falsa" />FAKE</label> <label><input type="radio" name="c2" value="real" />REAL</label> <label><input type="radio" name="c2" value="verificar" />Hay que verificarlo</label></div>
<div class="fn5-fb"><span class="marca"></span><span class="txt"></span><br /></div>
</fieldset><fieldset class="fn5-caso" data-key="c3"><legend>CASO 03</legend>
<blockquote>«Una foto muestra a un tiburón nadando por una autopista completamente inundada tras el paso de un huracán».</blockquote>
<div class="fn5-ops"><label><input type="radio" name="c3" value="falsa" />FAKE</label> <label><input type="radio" name="c3" value="real" />REAL</label> <label><input type="radio" name="c3" value="verificar" />Hay que verificarlo</label></div>
<div class="fn5-fb"><span class="marca"></span><span class="txt"></span><br /></div>
</fieldset><fieldset class="fn5-caso" data-key="c4"><legend>CASO 04</legend>
<blockquote>«Los pulpos tienen tres corazones y su sangre es de color azul».</blockquote>
<div class="fn5-ops"><label><input type="radio" name="c4" value="falsa" />FAKE</label> <label><input type="radio" name="c4" value="real" />REAL</label> <label><input type="radio" name="c4" value="verificar" />Hay que verificarlo</label></div>
<div class="fn5-fb"><span class="marca"></span><span class="txt"></span><br /></div>
</fieldset><fieldset class="fn5-caso" data-key="c5"><legend>CASO 05</legend>
<blockquote>«En sus orígenes, Coca-Cola era de color verde, pero la empresa decidió cambiarlo».</blockquote>
<div class="fn5-ops"><label><input type="radio" name="c5" value="falsa" />FAKE</label> <label><input type="radio" name="c5" value="real" />REAL</label> <label><input type="radio" name="c5" value="verificar" />Hay que verificarlo</label></div>
<div class="fn5-fb"><span class="marca"></span><span class="txt"></span><br /></div>
</fieldset>
<div id="fn5Rango" style="display: none; margin-top: 14px; border-top: 2px solid #000; padding-top: 14px;">
<p id="fn5RangoTxt" style="font-family: Georgia,serif; font-size: 17px; font-weight: bold;"></p>
<button type="button" class="fn5-btn" id="fn5Reset">Repetir el reto</button></div>
</form></section>
<!-- ============ RETO 2: JUEGO DE IDENTIFICAR PISTAS ============ -->
<section class="fn5-sec">
<p class="fn5-k">Reto 2 · Juego de identificación</p>
<h2>Caza las pistas del bulo</h2>
<p>Esta publicación viral simulada contiene <strong>6 señales de alerta</strong> que delatan que es un bulo. Haz clic solo sobre los elementos sospechosos (los que llevan borde punteado). Pista acertada: <strong>+25 puntos</strong>. Clic erróneo: <strong>−10 puntos</strong>.</p>
<div class="fn5-marcador" aria-live="polite"><span class="pill">Pistas: <span id="fn5Pistas">0</span>/6</span> <span class="pill">Puntos: <span id="fn5PtsJuego">0</span></span> <span class="pill">Errores: <span id="fn5Errores">0</span></span></div>
<div class="fn5-captura" id="fn5Post">
<p style="margin: 0 0 6px; font-weight: bold;">Publicación viral</p>
<p style="margin: 0 0 10px;">Cuenta: <span class="fn5-cand" data-pista="1">MegaNoticias24h_Urgente99_TruthOficial ✔</span>  ·  <span class="fn5-cand" data-pista="0">Hoy, 09:14</span></p>
<p style="margin: 0 0 10px;"><span class="fn5-cand" data-pista="1">«Los médicos lo confirman: llevan 40 años ocultándolo»</span> — <span class="fn5-cand" data-pista="1">este truco casero elimina la migraña en 10 minutos para siempre</span> — <span class="fn5-cand" data-pista="0">#BienestarNatural</span></p>
<div class="fn5-img"><span class="fn5-cand" data-pista="1">[FOTO: un frasco de laboratorio con líquido dorado — sin fecha, sin lugar, sin autor]</span></div>
<p style="margin: 0 0 10px;"><span class="fn5-cand" data-pista="1">«Mi tía es enfermera y me lo confirmó por WhatsApp»</span></p>
<div class="fn5-metricas"><span class="fn5-cand" data-pista="1">🔁 480.000 compartidos · ❤️ 1,2 M de reacciones · «¡ESTÁ EXPLOTANDO!»</span>  ·  <span class="fn5-cand" data-pista="0">Comentarios (3.412)</span>  ·  <span class="fn5-cand" data-pista="0">Botón: Compartir</span></div>
</div>
<p class="fn5-hint" id="fn5HintJuego" role="status"></p>
<div class="fn5-resumen" id="fn5Resumen">
<h3>Las 6 pistas que delataban el bulo</h3>
<ol>
<li><strong>Cuenta anónima con apariencia oficial:</strong> nombre con números y guiones bajos, y una marca de verificación imitada. Los medios reales tienen cuentas verificables.</li>
<li><strong>«Los médicos lo confirman… ocultándolo»:</strong> fuente genérica sin nombre + teoría conspirativa. Ningún «ellos» oculta nada en bloque.</li>
<li><strong>Promesa milagrosa:</strong> «elimina… en 10 minutos para siempre». Lo que cura todo no lo cura nada; la medicina no trabaja con promesas absolutas.</li>
<li><strong>Imagen sin fecha, lugar ni autor:</strong> cualquier foto real tiene origen. Sin contexto, puede ser de otra época, otro país o generada por IA.</li>
<li><strong>Testigo anónima:</strong> «mi tía es enfermera» no es verificable y puede ser cualquiera o nadie.</li>
<li><strong>Viralidad como argumento:</strong> 480.000 compartidos solo significan que 480.000 personas no lo comprobaron antes de reenviar. Popular no es verdadero.</li>
</ol>
<button type="button" class="fn5-btn" id="fn5ResetJuego">Jugar de nuevo</button></div>
</section>
<!-- ============ RETO 3: PANEL DE VERIFICACIÓN ============ -->
<section class="fn5-sec">
<p class="fn5-k">Tu caja de herramientas</p>
<h2>Recursos de verificación</h2>
<p>Antes de compartir cualquier cosa extraordinaria, pásala por aquí. Los tres primeros son agencias de verificación profesional en español (miembros de la red internacional IFCN de Poynter). Se abren en una pestaña nueva.</p>
<ul class="fn5-links">
<li><a href="https://maldita.es" target="_blank" rel="noopener">Maldita.es →</a> <span class="que">Verificación de bulos en español: política, salud, leyendas urbanas y cadenas de WhatsApp. Tiene buscador propio de bulos por palabras clave.</span></li>
<li><a href="https://www.newtral.es" target="_blank" rel="noopener">Newtral →</a> <span class="que">Agencia española de verificación (Fundación Newtral). Secciones «Tu derecho a saber» y chequeo de declaraciones políticas y virales.</span></li>
<li><a href="https://chequeado.com" target="_blank" rel="noopener">Chequeado →</a> <span class="que">Referente de verificación en español de Latinoamérica (Argentina). Excelente para discursos públicos, cifras y viralidad regional.</span></li>
<li><a href="https://verifica.efe.com" target="_blank" rel="noopener">EFE Verifica →</a> <span class="que">Desmentidos de EFE, la principal agencia de noticias en español. Muy útil para desinformación geopolítica y actualidad internacional.</span></li>
<li><a href="https://images.google.com" target="_blank" rel="noopener">Google Imágenes (búsqueda inversa) →</a> <span class="que">No es un verificador: es tu lupa. Arrastra cualquier imagen sospechosa y descubre cuándo apareció por primera vez y con qué texto original.</span></li>
<li><a href="https://www.snopes.com" target="_blank" rel="noopener">Snopes →</a> <span class="que">En inglés: el archivo de desmentidos más veterano de internet. Si un bulo lleva años circulando, casi seguro está documentado aquí.</span></li>
</ul>
<div class="fn5-pasos">
<p style="margin: 0;"><strong>El hábito de los 30 segundos:</strong> 1) Lee con calma y localiza la fuente original. 2) Haz una búsqueda inversa si hay imagen. 3) Busca el titular entre comillas en Maldita o EFE Verifica. 4) Si sigue sin aclararse, <em>no lo compartas</em>: la duda es una salida honorable de la caverna.</p>
</div>
</section>
<!-- ============ NAVEGACIÓN ============ --> <!-- Nota: ajusta el href si tu página 4 se exporta con otro nombre. --><nav class="fn5-nav" style="margin-top: 40px; padding-top: 20px; border-top: 1px solid #000; display: flex; flex-wrap: wrap; gap: 14px; justify-content: space-between; align-items: center;" aria-label="Navegación de la unidad">
<p>Con estos tres retos has practicado lo más difícil: desconfiar de lo que te da la razón y comprobar antes de compartir.</p>
<br /></nav></div>
<p>
<script>
(function(){
'use strict';
function $(id){return document.getElementById(id);}

/* ============ RETO 1: QUIZ ¿FAKE O REAL? ============ */
var RESP={c1:'falsa',c2:'real',c3:'falsa',c4:'real',c5:'falsa'};
var EXPL={
 c1:'FAKE. Ninguna alineación planetaria puede proyectar sombra sobre la Tierra: los demás planetas están a millones de kilómetros. Este bulo circula desde 2015 cambiando solo la fecha. Desmentido por NASA, Maldita.es y Newtral.',
 c2:'REAL. Es un efecto de dilatación térmica: el hierro se expande con el calor, así que la torre crece hasta unos 15 cm y se inclina ligeramente alejándose del sol. Lo documenta la sociedad que gestiona el monumento.',
 c3:'FAKE. La foto está manipulada: el tiburón procede de otra imagen. Circula desde 2005 y reaparece tras cada gran huracán (Harvey, Irma, Florence…). Desmentida por Snopes, Reuters y AFP Factual.',
 c4:'REAL. Dos corazones branquiales bombean sangre a las branquias y un tercero al resto del cuerpo; su sangre es azulada por la hemocianina. Lo recogen cualquier manual de biología marina y museos científicos.',
 c5:'FAKE. El líquido nunca fue verde: el bulo nace de la confusión con el vidrio verdoso de las botellas originales («Georgia green»). Desmentido por la propia empresa y por Snopes.'
};
var pts=0,hechos=0;
function marca(){ $('fn5Pts').textContent=pts; $('fn5Hechos').textContent=hechos; }
Array.prototype.slice.call(document.querySelectorAll('.fn5-caso')).forEach(function(fs){
  var key=fs.getAttribute('data-key');
  Array.prototype.slice.call(fs.querySelectorAll('input[type=radio]')).forEach(function(r){
    r.addEventListener('change',function(){
      if(fs.getAttribute('data-hecho'))return;
      fs.setAttribute('data-hecho','1');
      var elegida=this.value,correcta=RESP[key],ganancia=0,mensaje='';
      if(elegida===correcta){ganancia=20;mensaje='✓ Correcto';}
      else if(elegida==='verificar'){ganancia=10;mensaje='△ Buen instinto: verificar siempre es mejor que creer o descartar sin más. La respuesta definitiva:';}
      else{ganancia=0;mensaje='✗ Incorrecto';}
      pts+=ganancia;hechos++;marca();
      Array.prototype.slice.call(fs.querySelectorAll('input')).forEach(function(i){i.disabled=true;});
      Array.prototype.slice.call(fs.querySelectorAll('.fn5-ops label')).forEach(function(l){l.style.cursor='default';});
      var fb=fs.querySelector('.fn5-fb');
      fb.style.display='block';
      fb.querySelector('.marca').textContent=mensaje+(ganancia>0?' · +'+ganancia+' puntos':'');
      fb.querySelector('.txt').innerHTML='<b>Verificación posterior:</b> '+EXPL[key];
      if(hechos===5){
        var rt=$('fn5RangoTxt'),txt;
        if(pts===100){txt='100 puntos — Detector de nivel experto. Las sombras ya no te cogen desprevenido.';}
        else if(pts>=60){txt=pts+' puntos — Buen ojo. Eres capaz de dudar de lo conveniente: repasa los casos fallados y a por el 100.';}
        else{txt=pts+' puntos — Las sombras te retienen aún. Vuelve a la página 4 (expedientes y mecanismos psicológicos) y reintenta: no hay penalización.';}
        rt.textContent=txt;
        $('fn5Rango').style.display='block';
      }
    });
  });
});
 $('fn5Reset').addEventListener('click',function(){
  pts=0;hechos=0;marca();
  Array.prototype.slice.call(document.querySelectorAll('.fn5-caso')).forEach(function(fs){
    fs.removeAttribute('data-hecho');
    Array.prototype.slice.call(fs.querySelectorAll('input')).forEach(function(i){i.disabled=false;i.checked=false;});
    var fb=fs.querySelector('.fn5-fb');fb.style.display='none';
  });
  $('fn5Rango').style.display='none';
  window.scrollTo({top:0,behavior:'smooth'});
});

/* ============ RETO 2: JUEGO DE IDENTIFICAR PISTAS ============ */
var totalPistas=6,encontradas=0,ptsJuego=0,errores=0;
var NOPISTA='Ese elemento es normal en cualquier publicación: no es señal de alerta. Sigue buscando (−10 puntos).';
function marcaJuego(){
  $('fn5Pistas').textContent=encontradas;
  $('fn5PtsJuego').textContent=ptsJuego;
  $('fn5Errores').textContent=errores;
}
Array.prototype.slice.call(document.querySelectorAll('.fn5-cand')).forEach(function(el){
  el.addEventListener('click',function(){
    if(el.classList.contains('ok'))return;
    if(el.getAttribute('data-pista')==='1'){
      el.classList.add('ok');
      encontradas++;ptsJuego+=25;marcaJuego();
      $('fn5HintJuego').textContent='✓ ¡Pista detectada! +25 puntos';
      if(encontradas===totalPistas){
        $('fn5HintJuego').textContent='';
        $('fn5Resumen').classList.add('visible');
      }
    }else{
      errores++;ptsJuego=Math.max(0,ptsJuego-10);marcaJuego();
      $('fn5HintJuego').textContent='✗ '+NOPISTA;
    }
  });
});
 $('fn5ResetJuego').addEventListener('click',function(){
  encontradas=0;ptsJuego=0;errores=0;marcaJuego();
  Array.prototype.slice.call(document.querySelectorAll('.fn5-cand')).forEach(function(el){el.classList.remove('ok');});
  $('fn5HintJuego').textContent='';
  $('fn5Resumen').classList.remove('visible');
  window.scrollTo({top:document.getElementById('fn5Post').offsetTop-80,behavior:'smooth'});
});
})();
</script>
