<script>
(function(){
'use strict';
function $(id){return document.getElementById(id);}

/* ---------- Actividad: ordenar los pasos ---------- */
var ORDEN=['stop','inv','find','trace','cierre'];
var cont=$('s6Orden');
function tarjetas(){return Array.prototype.slice.call(cont.querySelectorAll('.s6-card'));}
function limpiarVered(){tarjetas().forEach(function(t){t.querySelector('.vered').textContent='';});}
function mover(card,dir){
  var lista=tarjetas(),i=lista.indexOf(card),j=i+dir;
  if(j<0||j>=lista.length)return;
  if(dir===-1)cont.insertBefore(card,lista[j]);
  else cont.insertBefore(lista[j],card);
  limpiarVered();$('s6Msg').textContent='';
}
tarjetas().forEach(function(t){
  t.querySelectorAll('.s6-mv').forEach(function(b){
    b.addEventListener('click',function(){mover(t,parseInt(b.getAttribute('data-dir'),10));});
  });
});
 $('s6Comprobar').addEventListener('click',function(){
  var pts=0;
  tarjetas().forEach(function(t,i){
    var ok=t.getAttribute('data-key')===ORDEN[i];
    t.querySelector('.vered').textContent=ok?'✓':'✗';
    if(ok)pts+=20;
  });
  $('s6Pts').textContent=pts;
  $('s6Msg').textContent=(pts===100)
    ?'¡Perfecto! Has construido tu linterna: Stop, Investigate, Find, Trace y cierre.'
    :'Revisa las posiciones marcadas con ✗, reordena y vuelve a comprobar.';
});
 $('s6Barajar').addEventListener('click',function(){
  var lista=tarjetas();
  for(var i=lista.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));cont.insertBefore(lista[j],lista[i]);lista=Array.prototype.slice.call(cont.querySelectorAll('.s6-card'));}
  limpiarVered();$('s6Pts').textContent='0';$('s6Msg').textContent='';
});
})();
</script>
