        border: 2px dashed #ccc;
        border-radius: 8px;
        margin: 10px 0;
        padding: 10px;
        transition: all 0.3s;
    }
    .drop-zone.drag-over { background: #d6eaf8; border-color: var(--info); }
    .drop-zone.filled { border-style: solid; background: #f0f0f0; }

