<script>
    let totalScore = 0;

    // DRAG AND DROP
    let draggedItem = null;

    document.querySelectorAll('.drag-item').forEach(item => {
        item.addEventListener('dragstart', function(e) {
            draggedItem = this;
            setTimeout(() => this.classList.add('dragging'), 0);
        });

        item.addEventListener('dragend', function() {
            this.classList.remove('dragging');
            draggedItem = null;
        });
    });

    document.querySelectorAll('.drop-zone').forEach(zone => {
        zone.addEventListener('dragover', function(e) {
            e.preventDefault();
            this.classList.add('drag-over');
        });

        zone.addEventListener('dragleave', function() {
            this.classList.remove('drag-over');
        });

        zone.addEventListener('drop', function(e) {
            e.preventDefault();
            this.classList.remove('drag-over');

            if (draggedItem && !this.classList.contains('filled')) {
                this.appendChild(draggedItem);
                this.classList.add('filled');
                draggedItem.classList.remove('dragging');
            }
        });
    });

    function checkOrder() {
        const zones = document.querySelectorAll('.drop-zone');
        let correct = 0;
        let total = zones.length;

        zones.forEach(zone => {
            const item = zone.querySelector('.drag-item');
            if (item) {
                const itemOrder = parseInt(item.dataset.order);
                const zonePosition = parseInt(zone.dataset.position);

                if (itemOrder === zonePosition) {
                    item.classList.add('correct');
                    correct++;
                } else {
                    item.classList.add('wrong');
                }
            }
        });

        if (correct === total) {
            totalScore += 50;
            document.getElementById('totalScore').textContent = totalScore;
            alert(`🎉 ¡Perfecto! Ordenaste correctamente todos los pasos del método SIFT. +50 puntos.`);
        } else {
            alert(`⚠️ Acertaste ${correct} de ${total} pasos. Revisa el orden correcto e inténtalo de nuevo.`);
        }
    }

    function resetOrder() {
        const zones = document.querySelectorAll('.drop-zone');
        const sourceColumn = document.querySelector('.drag-column');

        zones.forEach(zone => {
            const item = zone.querySelector('.drag-item');
            if (item) {
                sourceColumn.appendChild(item);
                item.classList.remove('correct', 'wrong');
            }
            zone.classList.remove('filled');
        });
    }

    // CASO PRÁCTICO
    function checkCaseAnswers() {
        const q1 = document.querySelector('input[name="q1"]:checked');
        const q2 = document.querySelector('input[name="q2"]:checked');
        const q3 = document.querySelector('input[name="q3"]:checked');
        const q4 = document.querySelector('input[name="q4"]:checked');

        if (!q1 || !q2 || !q3 || !q4) {
            alert('⚠️ Por favor, responde todas las preguntas antes de comprobar.');
            return;
        }

        let correct = 0;
        if (q1.value === 'b') correct++;
        if (q2.value === 'a') correct++;
        if (q3.value === 'a') correct++;
        if (q4.value === 'a') correct++;

        const feedback = document.getElementById('caseFeedback');
        feedback.style.display = 'block';

        if (correct === 4) {
            feedback.style.background = '#d4edda';
            feedback.style.color = '#155724';
            feedback.innerHTML = `🎉 <strong>¡Perfecto!</strong> Has aplicado correctamente el método SIFT. +50 puntos.<br><br>
            <strong>Conclusión:</strong> Esta es una FAKE NEWS. El blog no es fiable, no hay estudio de Harvard, y el lenguaje alarmista es una señal de manipulación.`;
            totalScore += 50;
            document.getElementById('totalScore').textContent = totalScore;
        } else {
            feedback.style.background = '#fff3cd';
            feedback.style.color = '#856404';
            feedback.innerHTML = `⚠️ Acertaste <strong>${correct}</strong> de 4 preguntas.<br><br>
            <strong>Respuestas correctas:</strong><br>
            1. b) Detenerme y preguntarme si el lenguaje alarmista es una señal de alerta<br>
            2. a) Buscar información sobre el blog para ver si es fiable<br>
            3. a) Buscar en Google para ver si otros medios lo confirman<br>
            4. a) Buscar el estudio original de Harvard para verificar si existe<br><br>
            <strong>Conclusión:</strong> Esta es una FAKE NEWS. El blog no es fiable, no hay estudio de Harvard, y el lenguaje alarmista es una señal de manipulación.`;
        }
    }

    function showFinalScore() {
        alert(`🏆 ¡Has completado todas las actividades!\n\nTu puntuación final: ${totalScore} / 100 puntos\n\n${totalScore === 100 ? '🎉 ¡Excelente! Has demostrado un gran pensamiento crítico.' : '💪 ¡Buen trabajo! Sigue practicando para mejorar.'}`);
    }
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

