.p7-links li.sin-enlace b{font-family:Georgia,serif;font-size:15.5px}

/* Navegación */
.p7-nav{margin-top:40px;padding-top:20px;border-top:1px solid #000;display:flex;flex-wrap:wrap;gap:14px;justify-content:space-between;align-items:center}
