<p>
<script>
(function(){
'use strict';
function $(id){return document.getElementById(id);}
function setLS(k,v){try{localStorage.setItem(k,v);}catch(e){}}
function getLS(k){try{return localStorage.getItem(k);}catch(e){return null;}}

/* ---------- Autoevaluación con rúbrica ---------- */
var AE=['ae1','ae2','ae3','ae4'];
function puntua(){
  var total=0,respondidas=0;
  AE.forEach(function(n){
    var sel=document.querySelector('input[name="'+n+'"]:checked');
    if(sel){total+=parseInt(sel.value,10);respondidas++;}
  });
  $('p7AePts').textContent=respondidas<4?'—':String(total);
  var msg=$('p7AeMsg');
  if(respondidas<4){msg.textContent='Responde los cuatro criterios para ver tu resultado.';return;}
  var t;
  if(total>=7){t='Evaluación honesta de un trabajo sólido. Y ahora lo más difícil: que la próxima obra supere esta. Ya sabes el camino.';}
  else if(total>=4){t='Vas por buen camino. Los criterios donde anotaste 0 o 1 no son un veredicto: son tu siguiente lista de tareas concretas.';}
  else{t='Reconocerlo es el primer acto de pensamiento crítico de esta página. Vuelve al mapa mínimo de la página 6 y rehace la parte floja: ninguna obra se termina a la primera, se termina revisándola.';}
  msg.textContent=t;
}
AE.forEach(function(n){
  var saved=getLS('p7-'+n);
  Array.prototype.slice.call(document.querySelectorAll('input[name="'+n+'"]')).forEach(function(r){
    if(saved!==null&&r.value===saved)r.checked=true;
    r.addEventListener('change',function(){setLS('p7-'+n,r.value);puntua();});
  });
});
puntua();
 $('p7AeReset').addEventListener('click',function(){
  AE.forEach(function(n){
    try{localStorage.removeItem('p7-'+n);}catch(e){}
    Array.prototype.slice.call(document.querySelectorAll('input[name="'+n+'"]')).forEach(function(r){r.checked=false;});
  });
  puntua();
});

/* ---------- Encuesta ---------- */
var ENC=['e1','e2','e3','e4','e5','e6'];
function encuenta(){
  var hechas=0;
  ENC.forEach(function(n){if(document.querySelector('input[name="'+n+'"]:checked'))hechas++;});
  $('p7EncHechos').textContent=hechas;
}
ENC.forEach(function(n){
  var saved=getLS('p7-'+n);
  Array.prototype.slice.call(document.querySelectorAll('input[name="'+n+'"]')).forEach(function(r){
    if(saved!==null&&r.value===saved)r.checked=true;
    r.addEventListener('change',function(){
      setLS('p7-'+n,r.value);
      encuenta();
      var e=$('p7EncEstado');e.textContent='Guardado.';
      setTimeout(function(){e.textContent='';},2000);
    });
  });
});
encuenta();
var encCom=$('p7EncCom');
try{var encPrev=getLS('p7-enc-com');if(encPrev)encCom.value=encPrev;}catch(e){}
 $('p7EncGuardar').addEventListener('click',function(){
  setLS('p7-enc-com',encCom.value);
  var e=$('p7EncEstado2');e.textContent='Comentario guardado en este navegador.';
  setTimeout(function(){e.textContent='';},2600);
});

/* ---------- Reflexión metacognitiva ---------- */
var ta=$('p7Cadenas'),comp=$('p7Compromiso');
try{var r1=getLS('p7-cadenas');if(r1)ta.value=r1;var r2=getLS('p7-compromiso');if(r2)comp.value=r2;}catch(e){}
 $('p7Guardar').addEventListener('click',function(){
  setLS('p7-cadenas',ta.value);
  setLS('p7-compromiso',comp.value);
  var e=$('p7Estado');e.textContent='Reflexión y compromiso guardados en este navegador.';
  setTimeout(function(){e.textContent='';},2600);
});

/* ---------- Botón: imprimir la hoja de cierre ---------- */
 $('p7Pdf').addEventListener('click',function(){window.print();});
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
